import { randomUUID } from 'crypto';
import { z } from 'zod';
import {
  DesignReferenceRequestSchema,
  DesignReferenceSearchRequestSchema,
} from '../../types/design-library';
import {
  LibraryRequestError,
  ensureHub,
  libraryErrorDetails,
  requestHub,
} from '../../library/HubClient';
import { currentLibraryRoot } from '../../services/ProjectLibrary';
import { getConfigManager } from '../../services/ConfigManager';
import {
  ProfileRuntimeSchema,
  ProfileVariantInputSchema,
} from '../../types/design-profile';
import { parseCommandContext, isCommandResult } from './shared';
import { booleanFlag, stringFlag } from '../flags';
import { sourceRefreshScope } from '../sourceRefresh';
import {
  ReferenceDiscoveryRequestSchema,
  AuthenticatedReferenceProviderSchema,
  ReferenceProviderSchema,
} from '../../types/reference-connectors';
import {
  ReferencePlanRequestSchema,
  ReferenceApprovalSchema,
  ReferenceOnboardingActionSchema,
} from '../../types/reference-onboarding';
import { errorResult, okResult, type CliCommandResult } from '../envelope';
import {
  CALLER_RUNNER_PATHS_ENV,
  resolveCallerRunnerPaths,
} from '../callerRunnerPaths';
import { errorMessage } from '../../utils/errorMessage';
import { subprocessEnvironment } from '../../utils/subprocessEnvironment';
import { handleProfileDisconnect } from './profileDisconnect';

const PROFILE_REQUEST_TIMEOUT_MS = 55_000;
const PROFILE_SEARCH_TIMEOUT_MS = 120_000;

export const ensureProfileHub = ({
  isSourceSyncAllowed = true,
}: { isSourceSyncAllowed?: boolean } = {}) =>
  ensureHub({
    root: currentLibraryRoot(),
    isSourceSyncAllowed,
    env: {
      ...subprocessEnvironment('rivetRuntime'),
      [CALLER_RUNNER_PATHS_ENV]: JSON.stringify(resolveCallerRunnerPaths()),
    },
  });

export const handleProfile = async (
  args: string[],
): Promise<CliCommandResult> => {
  const action = args[0] ?? 'status';
  const command = `profile.${action}`;
  if (action === 'disconnect') {
    const context = parseCommandContext(command, args.slice(1));
    return isCommandResult(context)
      ? context
      : handleProfileDisconnect(context.flags.positionals);
  }
  const context = parseCommandContext(command, args.slice(1), {
    runtime: { takesValue: true },
    detail: { takesValue: false },
    collections: { takesValue: true },
    provider: { takesValue: true },
    revision: { takesValue: true },
    approve: { takesValue: false },
    title: { takesValue: true },
    text: { takesValue: true },
    files: { takesValue: true },
    query: { takesValue: true },
    source: { takesValue: true },
    limit: { takesValue: true },
    'request-id': { takesValue: true },
    evidence: { takesValue: true },
    'project-id': { takesValue: true },
    note: { takesValue: true },
    'image-file': { takesValue: true },
    all: { takesValue: false },
    preview: { takesValue: false },
  });
  if (isCommandResult(context)) return context;
  if (!getConfigManager().isAuthenticated())
    return errorResult(
      command,
      'AUTH_REQUIRED',
      'Sign in to Rivet before using design profiles',
    );
  try {
    const selected =
      stringFlag(context.flags, 'runtime') ??
      context.handoff?.agent ??
      getConfigManager().getConfiguredRunner();
    const runtime =
      [
        'status',
        'diagnostics',
        'references',
        'reference',
        'pins',
        'inspect',
        'disable',
        'autonomy',
        'pause',
        'resume',
        'retry',
        'discover',
        'import',
        'onboarding',
      ].includes(action) ||
      (action === 'plan' && !stringFlag(context.flags, 'collections')) ||
      action === 'refresh'
        ? undefined
        : ProfileRuntimeSchema.parse(selected);
    let method = 'GET';
    let endpoint = '/profile';
    let body: unknown;
    switch (action) {
      case 'search': {
        method = 'POST';
        endpoint += '/search';
        body = DesignReferenceSearchRequestSchema.parse({
          query:
            stringFlag(context.flags, 'query') ??
            context.flags.positionals.join(' '),
          sourceId: stringFlag(context.flags, 'source'),
          limit: Number(stringFlag(context.flags, 'limit') ?? 24),
          runtime,
        });
        break;
      }
      case 'reference': {
        const [profileId, ...keys] = context.flags.positionals;
        method = 'POST';
        endpoint += '/reference-contexts';
        body = DesignReferenceRequestSchema.parse({
          profileId,
          keys,
          isDetailed: context.flags.values.detail === true,
        });
        break;
      }
      case 'discover': {
        method = 'POST';
        endpoint += '/discoveries';
        const value = z.tuple([z.string()]).parse(context.flags.positionals)[0];
        const provider = AuthenticatedReferenceProviderSchema.safeParse(value);
        body = ReferenceDiscoveryRequestSchema.parse(
          provider.success ? { provider: provider.data } : { url: value },
        );
        break;
      }
      case 'plan': {
        const id = z
          .tuple([z.string().uuid()])
          .parse(context.flags.positionals)[0];
        const collections = stringFlag(context.flags, 'collections');
        if (collections === undefined) {
          endpoint += `/import-plans/${id}`;
        } else {
          let ids: unknown;
          try {
            ids = JSON.parse(collections);
          } catch {
            return errorResult(
              command,
              'USAGE_ERROR',
              '--collections must be a JSON array of collection IDs',
            );
          }
          method = 'POST';
          endpoint += '/import-plans';
          body = ReferencePlanRequestSchema.parse({
            discoveryId: id,
            collectionIds: ids,
            runtime,
          });
        }
        break;
      }
      case 'import': {
        const id = z
          .tuple([z.string().uuid()])
          .parse(context.flags.positionals)[0];
        const approval = ReferenceApprovalSchema.parse({
          id,
          revision: stringFlag(context.flags, 'revision'),
          isApproved: context.flags.values.approve === true,
        });
        method = 'POST';
        endpoint += `/import-plans/${id}/imports`;
        body = { revision: approval.revision, isApproved: approval.isApproved };
        break;
      }
      case 'onboarding': {
        const choice = z
          .array(ReferenceOnboardingActionSchema)
          .max(1)
          .parse(context.flags.positionals)[0];
        const provider = ReferenceProviderSchema.optional().parse(
          stringFlag(context.flags, 'provider'),
        );
        endpoint += '/onboarding';
        if (!choice && provider) endpoint += `?provider=${provider}`;
        if (choice) {
          method = 'PATCH';
          body = { action: choice, ...(provider ? { provider } : {}) };
        }
        break;
      }
      case 'status':
        break;
      case 'diagnostics':
        endpoint += '/diagnostics';
        break;
      case 'rebuild-index':
        method = 'POST';
        endpoint += '/index-rebuilds';
        body = { runtime };
        break;
      case 'references':
        endpoint += '/references';
        break;
      case 'inspect': {
        const id = z
          .tuple([z.string().min(1).max(200)])
          .parse(context.flags.positionals)[0];
        endpoint += `/contexts/${encodeURIComponent(id)}`;
        break;
      }
      case 'pins': {
        const projectId = stringFlag(context.flags, 'project-id');
        endpoint += `/pins${projectId ? `?projectId=${encodeURIComponent(projectId)}` : ''}`;
        break;
      }
      case 'add-variant': {
        const [sessionId, variantId] = z
          .tuple([z.string().min(1), z.string().min(1)])
          .parse((context.flags.positionals[0] ?? '').split(':'));
        method = 'POST';
        endpoint += '/variants';
        body = ProfileVariantInputSchema.parse({
          projectId: stringFlag(context.flags, 'project-id'),
          sessionId,
          variantId,
          runtime,
          note: stringFlag(context.flags, 'note'),
          imageFile: stringFlag(context.flags, 'image-file'),
        });
        break;
      }
      case 'connect':
        method = 'POST';
        endpoint += '/sources';
        body = { runtime, url: context.flags.positionals[0] };
        break;
      case 'refresh': {
        const scope = sourceRefreshScope({
          family: 'references',
          positionals: context.flags.positionals,
          isAll: booleanFlag(context.flags, 'all'),
          isPreview: booleanFlag(context.flags, 'preview'),
        });
        const request =
          'sourceId' in scope
            ? {
                method: 'POST',
                endpoint: '/profile/source-sync/refreshes',
                body: { family: 'references', sourceId: scope.sourceId },
              }
            : scope;
        method = request.method;
        endpoint = request.endpoint;
        body = request.body;
        break;
      }
      case 'pause':
      case 'resume':
      case 'retry':
        method = 'PATCH';
        endpoint += `/jobs/${encodeURIComponent(context.flags.positionals[0] ?? '')}`;
        body = { action };
        break;
      case 'enable':
      case 'disable':
        method = 'PATCH';
        body = { runtime, isEnabled: action === 'enable' };
        break;
      case 'autonomy': {
        const [setting] = context.flags.positionals;
        if (setting !== 'on' && setting !== 'off')
          return errorResult(
            command,
            'USAGE_ERROR',
            'Usage: rivet profile autonomy <on|off>',
          );
        method = 'PATCH';
        body = { autonomousReferences: setting === 'on' };
        break;
      }
      case 'add-text':
        method = 'POST';
        endpoint += '/text';
        body = {
          runtime,
          title: stringFlag(context.flags, 'title') ?? 'Design notes',
          text: stringFlag(context.flags, 'text'),
          evidence: stringFlag(context.flags, 'evidence') ?? 'observation',
        };
        break;
      case 'add-images':
        method = 'POST';
        endpoint += '/images';
        body = {
          runtime,
          title: stringFlag(context.flags, 'title') ?? 'Image references',
          files: JSON.parse(stringFlag(context.flags, 'files') ?? '[]'),
        };
        break;
      case 'include':
      case 'exclude':
      case 'remove': {
        const id = context.flags.positionals[0];
        if (!id) throw new Error('A profile source ID is required');
        method = 'PATCH';
        endpoint += `/sources/${encodeURIComponent(id)}`;
        body = {
          runtime,
          ...(action === 'remove'
            ? { isRemoved: true }
            : { isIncluded: action === 'include' }),
        };
        break;
      }
      case 'suggest':
        method = 'POST';
        endpoint += '/preparations';
        body = {
          runtime,
          accountId: getConfigManager().getUserId(),
          requestId: stringFlag(context.flags, 'request-id') ?? randomUUID(),
          instruction: stringFlag(context.flags, 'query'),
          mode: 'auto',
        };
        break;
      default:
        return errorResult(
          command,
          'USAGE_ERROR',
          'Usage: rivet profile <status|diagnostics|discover|plan|import|onboarding|rebuild-index|enable|disable|autonomy|connect|disconnect|refresh|pause|resume|retry|add-text|add-images|pins|add-variant|inspect|references|reference|search|include|exclude|remove|suggest>',
        );
    }
    const hub = await ensureProfileHub();
    const result = await requestHub({
      hub,
      endpoint,
      method,
      body,
      timeoutMs:
        action === 'search'
          ? PROFILE_SEARCH_TIMEOUT_MS
          : PROFILE_REQUEST_TIMEOUT_MS,
    });
    return okResult(command, result);
  } catch (error) {
    return errorResult(
      command,
      error instanceof z.ZodError ? 'USAGE_ERROR' : 'OPERATION_FAILED',
      errorMessage(error, 'Profile operation failed'),
      error instanceof LibraryRequestError
        ? libraryErrorDetails(error)
        : undefined,
    );
  }
};
